Example 2 - VHDL (one_process.vhd)
Library IEEE;
Use IEEE.STD_Logic_1164.all;
Entity FSM1_BAD is
port (Clock:
in std_logic;
SlowRAM:
in std_logic;
Read,Write: out std_logic);
End entity FSM1_BAD;
Architecture RTL of FSM1_BAD is
Begin
SEQ_AND_COMB: process
variable State: integer;
wait until rising_edge(Clock);
case State is
when 0=>
Read <= '1';
State := 1;
When 1=>
Write <= '1';
if (SlowRAM = '1') then
State := 2;
Else
State := 0;
end if;

when 2=>
State := 0;
When others=> null;
end case;
end process SEQ_AND_COMB;
end architecture RTL;

Example 1 - Verilog (two_process.v)
module FSM1_GOOD (Clock, Reset, SlowRAM, Read, Write);
input Clock, Reset, SlowRAM;
output Read, Write;
reg Read,Write;
reg [1:0] CurrentState, NextState;
always @(posedge Clock)
begin: SEQ
if (Reset)
CurrentState = 0;
CurrentState = NextState;
end
always @(CurrentState or SlowRAM)
begin: COMB
case (CurrentState)
0 :
Read = 1;
Write = 0;
NextState = 1;
end
1 :
Read = 0;
Write = 1;
if (SlowRAM)
NextState = 2;
NextState = 0;
end
2 :
Read = 0;
Write = 0;
NextState = 1;
end
default :
Read = 0;
Write = 0;
NextState = 0;
end

Example 2 - VHDL (two_process.vhd)
library IEEE;
use IEEE.STD_Logic_1164.all;
entity FSM1_GOOD is
port (Clock, Reset: in std_logic;
SlowRAM:
in std_logic;
Read, Write: out std_logic);
end entity FSM1_GOOD;
architecture RTL of FSM1_GOOD is
type StateType is (ST_Read, ST_Write, ST_Delay);
signal CurrentState,NextState: StateType;
SEQ: process
Begin
wait until rising_edge(Clock);
if (Reset = '1') then
CurrentState <= ST_Read;
Else
CurrentState <= NextState;
end if;
end process SEQ;
COMB: process (CurrentState)
Begin
case CurrentState is
when ST_Read =>
Read <= '1';
NextState <= ST_Write;
when ST_Write =>
Write <= '1';
if (SlowRAM = '1') then
NextState <= ST_Delay;
Else
NextState <= ST_Read;
end if;
when ST_Delay =>
NextState <= ST_Read;
when others =>
NextState <= ST_Read;
end case;
end process COMB;
end architecture RTL;

