architecture RTL of FSM2_GOOD is
signal r,v: R1_Type;
SEQ: process
wait until rising_edge(Clock);
r <= v;
end process SEQ;
COMB: process (r)
case r.State is
when ST_Read =>
Read <= '1';
v.Output <= '1';
v.State <= ST_Write;
when ST_Write =>
Write <= '1';
v.Output <= '1';
if (SlowRAM = '1') then
v.State <= ST_Delay;
v.State <= ST_Read;
end if;
when ST_Delay =>
v.Output <= '1';
v.State <= ST_Read;
when others =>

when "10" =>
-- no push, pop
RdPntr_r <= (RdPntr_r + 1) mod Depth_g;
when "11" =>
-- no push, no pop
null;
when others => null;
end case;
if Resetn = '0' then
WrPntr_r <= 0;
RdPntr_r <= 0;
FIFO_r
<= (others => (others => '0'));
end if;
