regArr[p0][p1*0] = regArr[p0][idx0];
regArr[1'b0][0] = regArr[0][idx0+p0];
// left == right
st1.a[0] = st1[38];
st1.b = st1[37];
st1.c.sc[0] = st1[0];
st1.c.sc[0] = st1.c[0];
st1.c.sb = st1.c[33:2];
st1.c.sb = st1.c[33-:32];
st1.c.sb[0] = st1.c[2];
// compare constant index for bit-select
itg[1] = itg[2'b01];
itg[p1] = itg['h1];
