This argument specifies the module to be cloned.

This argument specifies the name of the new module.
On success, the cloned module handle is returned.
On failure, a null pointer is returned
typedef enum { ADD, SUB } ALU_OP;
typedef struct { logic a; logic b; logic cin; } OPERAND;
wire OPERAND op;

wire ALU_OP select;
wire out, carry, zero;
alu i0( op, select, out, carry, zero );
wire out1, carry1, zero1;
alu i1( op, select, out1, carry1, zero1 );
module alu( input OPERAND op,
input ALU_OP select,
output logic out,
output logic carry,
output zero);
case (select)
ADD: {carry,out} = op.a + op.b + op.cin;
SUB: {carry,out} = op.a - op.b - 1 + op.cin;
default: {carry,out} = 0;
end
assign zero = (out==0) ? 1 : 0;

