npi_dm_delete_db
Delete a DM database (DMDB).
The default DMDB cannot be deleted. If the DMDB to be deleted is the master
DMDB, the default DMDB is set as the master DMDB.

NPI_INT32 npi_dm_delete_db( npiDmDb dmdb );

dmdb

This argument specifies the DMDB to be deleted.

{
//-- DM
operation---------------------------------------------------------// Initialy, DM creates a default dmdb
npiDmDb default_dmdb = npi_dm_get_master_db();
// Operate on the default DMDB.
npi_dm_add_var( top, "default_a", NULL, NULL );
npi_dm_write_text_mode( "DEFAULT_DM_LIB" );
// User can create their own DMDB and set as the master DMDB.
npiDmDb dmdb
= npi_dm_create_db( "user.dmdb" );
int
result = npi_dm_set_master_db( dmdb );
// Operate on the user DMDB
npi_dm_add_var( top, "user_a", NULL, NULL );
npi_dm_write_text_mode( "USER_DM_LIB" );
// Delete the master DMDB, DM sets the default DMDB as the master DMDB.
result = npi_dm_delete_db( dmdb );
//-----------------------------------------------------------------------npi_end();

}

