entity sub is -- npiDmVhEntity
architecture arch_sub of sub is -- npiDmVhArchitecture
port(oo: out std_logic);
component add -- npiDmVhComponent
port(ea : in std_logic_vector(size-1 downto 0);
eb : in std_logic_vector(size-1 downto 0);
esum : out std_logic_vector(size-1 downto 0);
end component add;
-- npiDmVhInstance: instantiate add with component declaration
inst_add: add generic map(size => 32)
port map(a, b, cin, sum, cout);
-- npiDmVhInstance: instantiate sub with direct instantiation method
inst_sub: entity work.sub(arch_sub) port map(oo => oo);

port(ea : in std_logic_vector(size-1 downto 0);
eb : in std_logic_vector(size-1 downto 0);
esum : out std_logic_vector(size-1 downto 0);
end component add;
-- npiDmVhInstance
inst_add: add generic map(size => 32)
port map(a, b, ecin => cin, esum => sum, ecout => cout);

procedure add_procedure(signal x, y: in std_logic_vector(31 downto 0); -npiDmVhProcedure
signal sum: out std_logic_vector(31 downto 0)) is
sum <= x xor y;
end add_procedure;
seq_proc_call: add_procedure(a, y => b, sum => sum); -npiDmVhSeqProcCall

program test ;
event clk;
class A;
bit[1:0] a,b,c,d,e;
covergroup cg @(clk);
cpa : coverpoint a; /* coverpoint "cpa" will get 4 cover-bins due
to the bit size */
cpb : coverpoint b;
cpc : coverpoint c;
cr1 : cross cpa,cpb; /* cr1 can get coverpoints "cpa" and "cpb" by
1-to-many method "npiCovComponent" */
CR1 : cross cr1,cpc;
crossdXe : cross d, e {
bins bsub = binsof(d) intersect {0}; /* user defined bin whose
property npiCovBinName is "bsub" */
ignore_bins bignore = binsof(e) intersect {0}; /* ignore bin
whose property npiCovBinName is "bignore" */
}
endgroup
cg = new();
A a = new();
-> clk;
a.a = 2;
a.b = 0;
a.c = 1;
a.d = 1;
a.e = 1;
-> clk;
a.a = 1;
a.b = 2;
a.c = 0;
-> clk;
a.a = 3;
a.b = 1;
a.c = 2;
-> clk;
end
endprogram

