void trace_driver(npiNlHandle hdl, FILE* fp)
{
nlHdlVec_t dHdlVec;
nlHdlVec_t::iterator it;
if(npi_vanl_driver_by_hdl(hdl, dHdlVec/*O*/) == 0)
{
fprintf (fp, "-> %s, (%s)\n",
npi_nl_ut_get_hdl_info(hdl),
npi_vanl_get_value_by_hdl(hdl, npiNlBinFormat));
}
for (it = dHdlVec.begin(); it != dHdlVec.end(); ++it)
trace_driver(*it, fp);
}
{
npi_vanl_begin ("top");
