npi_vanl_report_all_path
Get all paths in combinational circuit from specific signals to signals based on NPI VANL
Library. The result path is collected into a specified vector (C++) or array (Tcl). It does not
pass through registers. For more information about active trace rule, see Rules for Active
Trace.

int npi_vanl_report_all_path ( nlHdlVec_t& fromHdlVec/*I*/, nlHdlVec_t&
throughHdlVec/*I*/, nlHdlVec_t& toHdlVec/*I*/, nlHdlVecVec_t&
hdlPathVec/*O*/, bool isAndThrough/* = true*/, bool activeTrace = true);

fromHdlVec

Specifies the reference of the vector from which signal it starts trace load to find path.
throughHdlVec

Specifies the reference of vector, which the path should pass through.
toHdlVec

Specifies the reference of vector, to which signal find path traces.
hdlPathVec

Specifies the reference of vector where path is collected and nlHdlVecVec_t is a typedefine for vector <vector <npiNlHandle> >.
isAndThrough

A boolean value specifying whether or not the signals in throughHdlVec are treated as
AND type or OR type. It's default value is true, which means AND.

Returns the total number of paths.

wire wtmp, wo;
end
end
assign wo = ~wtmp;
wout<=wo;
end

{
nlHdlVec_t fromHdlVec, throughHdlVec, toHdlVec;
nlHdlVecVec_t pathVec;
hdl = npi_nl_L1_handle_by_name("TOP.wtmp1", npiNlNet);
if (hdl)
fromHdlVec.push_back(hdl);
hdl = npi_nl_L1_handle_by_name("TOP.wtmp", npiNlNet);
if (hdl)
throughHdlVec.push_back(hdl);
hdl = npi_nl_L1_handle_by_name("TOP.wo", npiNlNet);
if (hdl)
toHdlVec.push_back(hdl);
int ret = npi_vanl_report_all_path (fromHdlVec, throughHdlVec,
toHdlVec, pathVec/*O*/, false);

for (i = 0; i < pathVec.size(); i++)
{
printf("Path %d:\n", i+1);
npi_nl_ut_dump_hdl_vec_info (pathVec[i], stdout);
}

}

