typeVec/*I*/, true);
npi_nl_ut_dump_hdl_vec_info(outHdlVec/*I*/, stdout);
printf("Reg input instports, filter away Clock port:\n");
sigHdl =
npi_nl_L1_handle_by_name((char*)"top.top:Always1Always0:4:6:Reg.ROH_r3
");
npi_nl_trace_driver_by_hdl2(sigHdl, hdlVec/*O*/);
npi_nl_ut_filter_port_instport(hdlVec/*I*/, outHdlVec/*O*/,
typeVec/*I*/, false);
