{
npiHandle hdl = npi_handle_by_name("top.sig", NULL);
npiHandle exprHdl = npi_handle(npiExpr, hdl);
stringVec_t bitVec;
int result = npi_get_bit_blasted_expr(exprHdl, bitVec /*O*/ );
cout << "Bit vector from MSB to LSB:" << endl;
for (auto str: bitVec)
