//determine the needed number of bits
int npi_tr_num_bits(NPI_INT64 val){
if( val>-100 && val<100 )
return 8;
else if( ( val >= 1e2 && val < 1e4 )
|| ( val <= -1e2 && val > -1e4 ) )
return 16;
else if( ( val >= 1e4 && val < 1e9 )
|| ( val <= -1e4 && val > -1e9 ) )
return 32;
else if( ( val >= 1e9 && val < 1e18 )
|| ( val <= -1e9 && val > -1e18 ) )
return 64;
}

return 64;

