NPI_INT32 npi_tr_writer::add_relation_API(npiTrRel rel,
npiFsdbwTransHandle trans1, npiFsdbwTransHandle trans2){
switch ( rel ) {
case npiTrParent:
return npi_fsdbw_add_relation(npiFsdbwRelParentChild, trans2,
trans1);
case npiTrPred:
return npi_fsdbw_add_relation(npiFsdbwRelPredSucc, trans2,
trans1 );
case npiTrChild:
return npi_fsdbw_add_relation(npiFsdbwRelParentChild, trans1,
trans2);
case npiTrSucc:
return npi_fsdbw_add_relation(npiFsdbwRelPredSucc, trans1, trans2);
}
}
