covergroup cg1;

virtual function void sample(uvm_reg_data_t data,
uvm_reg_data_r byte_en,
bit is_read,
uvm_reg_map map);
if (get_coverage(UVM_CVR_REG_BITS)) begin
m_current = get();
m_data = data;
m_is_read = is_read;
cg1.sample();
endif
