ind_data_reg IND_DATA;
ind_reg INDIRECT_REG[256];
foreach (INDIRECT_REG[i]) begin
string name = $sformatf("INDIRECT_REG[%0d]",i);
INDIRECT_REG[i]=
ind_reg::type_id::create(name,,get_full_name());
INDIRECT_REG[i].configure(this, null, );
INDIRECT_REG[i].build();
end
IND_IDX = ind_idx_reg::type_id::create(“IND_IDX”,,get_full_name());
IND_IDX.configure(this, null, );
IND_IDX.build();
IND_DATA = ind_data_reg::type_id::create(“IND_DATA”,,get_full_name());
IND_DATA.configure(IND_IDX, INDIRECT_REG, this, null);
IND_DATA.build();
default_map = create_map(““, 0, 4, UVM_BIG_ENDIAN);
default_map.add_reg(IND_IDX, 0);
default_map.add_reg(IND_DATA, 4);

