m_idx = idx;;
m_data = data;
m_addr = addr;
endfunction: new
virtual task body(uvm_reg_item rw);
m_idx_reg.write(status, m_addr, );
if (status != UVM_IS_OK)
return;
if (rw.kind == UVM_WRITE)
m_data.write(rw.status, data, );
else
m_data.read(rw.status, data, );
