R.configure(this, null, "R_reg");
R.build();

W = reg_WO::type_id::create("W");
W.configure(this, null, "W_reg");
W.build();

default_map.add_reg(R, 'h100, "RO");
default_map.add_reg(W, 'h100, "WO");
